import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.4s5LDCII.js";const _=JSON.parse('{"title":"AI 问答层缓行，二期只做\\"文献检索助手\\"","description":"","frontmatter":{},"headers":[],"relativePath":"project/adr/0004-ai-layer-deferred.md","filePath":"project/adr/0004-ai-layer-deferred.md"}'),n={name:"project/adr/0004-ai-layer-deferred.md"};function s(u,e,i,d,c,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-问答层缓行-二期只做-文献检索助手" tabindex="-1">AI 问答层缓行，二期只做&quot;文献检索助手&quot; <a class="header-anchor" href="#ai-问答层缓行-二期只做-文献检索助手" aria-label="Permalink to &quot;AI 问答层缓行，二期只做&quot;文献检索助手&quot;&quot;">​</a></h1><p>当前流行&quot;知识库 + AI 问答&quot;形态，但 MVP 明确不做 AI 层。原因：医疗语境下 AI 幻答的风险不可接受，且会让项目从&quot;权威转述&quot;滑向&quot;AI 生成&quot;，摧毁本项目赖以存在的信任与中立性，还叠加生成式内容在健康领域的合规风险。</p><p>二期若引入 AI，定位严格限定为<strong>文献检索助手</strong>：只返回原文出处与原句，不生成、不改写、不总结任何医学结论。这将来的读者会觉得反直觉——&quot;一个知识库居然没有 AI 问答？&quot;——故记录于此，防止后续被当作疏漏&quot;补上&quot;。</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>词条的 front-matter 结构必须从一开始就保持规整：它是将来 RAG 检索的地基，现在偷懒将来还债。</li><li>页面导读采用&quot;AI 起草初稿 + 人工逐条对照原文校验 + 统一免责声明&quot;的流程，与 AI 层的边界互不混淆：AI 可以辅助生产，但不直接面向用户生成答案。</li></ul>',5)])])}const p=t(n,[["render",s]]);export{_ as __pageData,p as default};
